import { FormEvent, useState } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

interface ProfileSettings {
  name: string;
  language: string;
  notifications: boolean;
}

interface SettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

export default function SettingsForm({ onSave }: SettingsFormProps) {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState('ru');
  const [notifications, setNotifications] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, notifications });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 16px)' }}
    >
      <JxInputField
        label="Имя"
        value={name}
        onChange={(event) => setName(event.target.value)}
      />
      <JxSelect
        label="Язык интерфейса"
        options={[
          { value: 'ru', label: 'Русский' },
          { value: 'en', label: 'English' },
        ]}
        value={language}
        onValueChange={setLanguage}
      />
      <JxSwitch
        label="Уведомления на почту"
        checked={notifications}
        onChange={(event) => setNotifications(event.target.checked)}
      />
      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </form>
  );
}

